//! Raw bindings to MLX-C, generated by bindgen at build time.
//!
//! Vendors MLX-C 0.8.0 (a26f2d584a14, pinned to MLX v0.32.4) and stays
//! API-compatible with crates.io `mlx-sys` 0.7.0 for `mlx-rs` 0.34: the only
//! breaking change, `mlx_gather_qmm` gaining `global_scale`, is bridged by
//! `vendor/compat`. The new function is `mlx_gather_qmm_gs`.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
